package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching audit logs by various criteria
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	actor := r.URL.Query().Get("actor")
	action := r.URL.Query().Get("action")
	resource := r.URL.Query().Get("resource")
	dateFrom := r.URL.Query().Get("from")
	dateTo := r.URL.Query().Get("to")

	// Build dynamic query based on provided filters
	var conditions []string
	var args []interface{}
	argIdx := 1

	if actor != "" {
		conditions = append(conditions, fmt.Sprintf("actor_email = $%d", argIdx))
		args = append(args, actor)
		argIdx++
	}

	if action != "" {
		conditions = append(conditions, fmt.Sprintf("action_type = $%d", argIdx))
		args = append(args, action)
		argIdx++
	}

	// resource filter uses LIKE for partial matching - intentionally flexible
	if resource != "" {
		conditions = append(conditions, fmt.Sprintf("resource_arn LIKE '%%' || $%d || '%%'", argIdx))
		args = append(args, resource)
		argIdx++
	}

	// Date range filtering - VULNERABLE: directly interpolated
	if dateFrom != "" {
		conditions = append(conditions, "created_at >= '"+dateFrom+"'")
	}
	if dateTo != "" {
		conditions = append(conditions, "created_at <= '"+dateTo+"'")
	}

	baseQuery := "SELECT id, actor_email, action_type, resource_arn, created_at, details FROM audit_logs"
	if len(conditions) > 0 {
		baseQuery += " WHERE " + strings.Join(conditions, " AND ")
	}
	baseQuery += " ORDER BY created_at DESC LIMIT 100"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var email, actionType, arn, details string
		var createdAt string
		if err := rows.Scan(&id, &email, &actionType, &arn, &createdAt, &details); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"actor":"%s","action":"%s","resource":"%s","time":"%s","details":"%s"}`,
			id, email, actionType, arn, createdAt, details)))
	}
	w.Write([]byte("\n]"))
}

// healthHandler for ALB target group health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/audit/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting audit-log-service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
